function visitNodes(nodes, paints, layers, roles) {
    for (const node of nodes) {
        if (node.layer)
            layers.add(node.layer);
        if (node.role)
            roles.add(node.role);
        if (node.paint?.fill)
            paints.add(node.paint.fill);
        if (node.paint?.stroke)
            paints.add(node.paint.stroke);
        if (node.paint?.color)
            paints.add(node.paint.color);
        if (node.children)
            visitNodes(node.children, paints, layers, roles);
    }
}
function variantUsesSemanticPaints(definition, variantName) {
    const variant = definition.variants?.[variantName];
    if (!variant)
        return false;
    if (variant.palette && Object.keys(variant.palette).length > 0)
        return true;
    const paints = new Set();
    visitNodes(variant.nodes ?? definition.nodes, paints, new Set(), new Set());
    return paints.size > 0;
}
/**
 * Derives renderer-neutral capabilities from the canonical definition.
 * Official icons and third-party/custom icons use exactly the same path.
 */
export function getIconCapabilities(definition) {
    const paints = new Set(Object.keys(definition.palette ?? {}));
    const layers = new Set();
    const roles = new Set();
    visitNodes(definition.nodes, paints, layers, roles);
    const variants = Object.keys(definition.variants ?? {}).sort();
    const colorVariants = [];
    for (const variantName of variants) {
        const variant = definition.variants?.[variantName];
        for (const token of Object.keys(variant?.palette ?? {}))
            paints.add(token);
        if (variant?.nodes)
            visitNodes(variant.nodes, paints, layers, roles);
        if (variantUsesSemanticPaints(definition, variantName))
            colorVariants.push(variantName);
    }
    const paintTokens = [...paints].sort();
    return Object.freeze({
        variants: Object.freeze(variants),
        ...(definition.defaultVariant ? { defaultVariant: definition.defaultVariant } : {}),
        paintTokens: Object.freeze(paintTokens),
        layers: Object.freeze([...layers].sort()),
        roles: Object.freeze([...roles].sort()),
        colorVariants: Object.freeze(colorVariants),
        supportsSemanticPaints: paintTokens.length > 0,
        supportsPaletteOverrides: paintTokens.length > 0,
        supportsLayerOverrides: layers.size > 0,
        multicolorCapable: paintTokens.length > 1,
    });
}
